import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  dropdownMenuBackdropClasses,
  dropdownMenuDestructiveItemClasses,
  dropdownMenuIconClasses,
  dropdownMenuIndicatorClasses,
  dropdownMenuInsetItemClasses,
  dropdownMenuItemClasses,
  dropdownMenuLabelClasses,
  dropdownMenuPopupClasses,
  dropdownMenuPortalClasses,
  dropdownMenuPositionerClasses,
  dropdownMenuRootClasses,
  dropdownMenuSeparatorClasses,
  dropdownMenuShortcutClasses,
  dropdownMenuSubContentClasses,
  dropdownMenuTriggerClasses,
} from "./view";

export {
  dropdownMenuBackdropClasses,
  dropdownMenuDestructiveItemClasses,
  dropdownMenuIconClasses,
  dropdownMenuIndicatorClasses,
  dropdownMenuInsetItemClasses,
  dropdownMenuItemClasses,
  dropdownMenuLabelClasses,
  dropdownMenuPopupClasses,
  dropdownMenuPortalClasses,
  dropdownMenuPositionerClasses,
  dropdownMenuRootClasses,
  dropdownMenuSeparatorClasses,
  dropdownMenuShortcutClasses,
  dropdownMenuSubContentClasses,
  dropdownMenuTriggerClasses,
} from "./view";

export type DropdownMenuStyle = Readonly<Record<string, string>>;

export type PartViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onToggle: ParentMessage;
  open?: boolean | undefined;
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type PortalViewConfig = Readonly<{
  open: boolean;
  children: readonly Html[];
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type BackdropViewConfig<ParentMessage> = Readonly<{
  onClose: ParentMessage;
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onSelect: ParentMessage;
  disabled?: boolean | undefined;
  inset?: boolean | undefined;
  destructive?: boolean | undefined;
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type CheckedItemViewConfig<ParentMessage> = ItemViewConfig<ParentMessage> &
  Readonly<{
    checked: boolean;
  }>;

export type RadioGroupViewConfig = Readonly<{
  children: readonly Html[];
  label?: string | undefined;
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

export type RadioItemViewConfig<ParentMessage> =
  ItemViewConfig<ParentMessage> &
    Readonly<{
      checked: boolean;
    }>;

export type SubTriggerViewConfig<ParentMessage> = Readonly<{
  children: readonly Html[];
  onOpen: ParentMessage;
  open?: boolean | undefined;
  disabled?: boolean | undefined;
  classes?: string | undefined;
  style?: DropdownMenuStyle | undefined;
}>;

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const itemClasses = ({
  classes,
  inset = false,
  destructive = false,
}: Readonly<{
  classes?: string | undefined;
  inset?: boolean | undefined;
  destructive?: boolean | undefined;
}>): string =>
  [
    dropdownMenuItemClasses,
    inset ? dropdownMenuInsetItemClasses : undefined,
    destructive ? dropdownMenuDestructiveItemClasses : undefined,
    classes,
  ]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.DataAttribute("slot", "dropdown-menu"),
      h.Class(cn(dropdownMenuRootClasses, classes)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  children,
  onToggle,
  open = false,
  classes,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("aria-haspopup", "menu"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      h.DataAttribute("slot", "dropdown-menu-trigger"),
      ...(open ? [h.DataAttribute("open", "true")] : []),
      h.OnClick(onToggle),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuTriggerClasses, classes)),
    ],
    children
  );
};

export const portalView = <ParentMessage>({
  open,
  children,
  classes,
  style,
}: PortalViewConfig): Html => {
  const h = html<ParentMessage>();

  if (!open) {
    return h.empty;
  }

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.DataAttribute("slot", "dropdown-menu-portal"),
      h.Class(cn(dropdownMenuPortalClasses, classes)),
    ],
    children
  );
};

export const backdropView = <ParentMessage>({
  onClose,
  classes,
  style,
}: BackdropViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel("Close dropdown menu"),
      h.OnClick(onClose),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.DataAttribute("slot", "dropdown-menu-backdrop"),
      h.Class(cn(dropdownMenuBackdropClasses, classes)),
    ],
    []
  );
};

export const positionerView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.DataAttribute("slot", "dropdown-menu-positioner"),
      h.Class(cn(dropdownMenuPositionerClasses, classes)),
    ],
    children
  );
};

export const popupView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menu"),
      h.DataAttribute("slot", "dropdown-menu-popup"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuPopupClasses, classes)),
    ],
    children
  );
};

export const shortcutView = <ParentMessage>(shortcut: string): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "dropdown-menu-shortcut"),
      h.Class(dropdownMenuShortcutClasses),
    ],
    [shortcut]
  );
};

export const itemView = <ParentMessage>({
  onSelect,
  children,
  disabled = false,
  inset = false,
  destructive = false,
  classes,
  style,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitem"),
      h.Disabled(disabled),
      h.DataAttribute("slot", "dropdown-menu-item"),
      ...(disabled
        ? [h.DataAttribute("disabled", "true")]
        : [h.OnClick(onSelect)]),
      ...(inset ? [h.DataAttribute("inset", "true")] : []),
      ...(destructive ? [h.DataAttribute("variant", "destructive")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(itemClasses({ classes, inset, destructive })),
    ],
    children
  );
};

export const checkboxItemView = <ParentMessage>({
  checked,
  onSelect,
  children,
  disabled = false,
  inset = false,
  classes,
  style,
}: CheckedItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitemcheckbox"),
      h.Attribute("aria-checked", checked ? "true" : "false"),
      h.Disabled(disabled),
      h.DataAttribute("slot", "dropdown-menu-checkbox-item"),
      ...(checked ? [h.DataAttribute("checked", "true")] : []),
      ...(disabled
        ? [h.DataAttribute("disabled", "true")]
        : [h.OnClick(onSelect)]),
      ...(inset ? [h.DataAttribute("inset", "true")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(itemClasses({ classes, inset })),
    ],
    children
  );
};

export const radioGroupView = <ParentMessage>({
  children,
  label,
  classes,
  style,
}: RadioGroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      ...(label === undefined ? [] : [h.AriaLabel(label)]),
      h.DataAttribute("slot", "dropdown-menu-radio-group"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classes ?? ""),
    ],
    children
  );
};

export const radioItemView = <ParentMessage>({
  checked,
  onSelect,
  children,
  disabled = false,
  inset = false,
  classes,
  style,
}: RadioItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitemradio"),
      h.Attribute("aria-checked", checked ? "true" : "false"),
      h.Disabled(disabled),
      h.DataAttribute("slot", "dropdown-menu-radio-item"),
      ...(checked ? [h.DataAttribute("checked", "true")] : []),
      ...(disabled
        ? [h.DataAttribute("disabled", "true")]
        : [h.OnClick(onSelect)]),
      ...(inset ? [h.DataAttribute("inset", "true")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(itemClasses({ classes, inset })),
    ],
    children
  );
};

export const subTriggerView = <ParentMessage>({
  onOpen,
  children,
  open = false,
  disabled = false,
  classes,
  style,
}: SubTriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.Attribute("role", "menuitem"),
      h.Attribute("aria-haspopup", "menu"),
      h.Attribute("aria-expanded", open ? "true" : "false"),
      h.Disabled(disabled),
      h.DataAttribute("slot", "dropdown-menu-sub-trigger"),
      ...(open ? [h.DataAttribute("open", "true")] : []),
      ...(disabled
        ? [h.DataAttribute("disabled", "true")]
        : [h.OnClick(onOpen)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(itemClasses({ classes })),
    ],
    children
  );
};

export const subContentView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "menu"),
      h.DataAttribute("slot", "dropdown-menu-sub-content"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuSubContentClasses, classes)),
    ],
    children
  );
};

export const itemIndicatorView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "dropdown-menu-item-indicator"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuIndicatorClasses, classes)),
    ],
    children
  );
};

export const iconView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "dropdown-menu-icon"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuIconClasses, classes)),
    ],
    children
  );
};

export const labelView = <ParentMessage>({
  children,
  classes,
  style,
}: PartViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "dropdown-menu-label"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuLabelClasses, classes)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  classes,
  style,
}: Omit<PartViewConfig, "children">): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "separator"),
      h.AriaHidden(true),
      h.DataAttribute("slot", "dropdown-menu-separator"),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(dropdownMenuSeparatorClasses, classes)),
    ],
    []
  );
};

export const dropdownMenuRootClasses = "relative inline-block text-left";

export const dropdownMenuTriggerClasses =
  "inline-flex items-center justify-center gap-2 rounded-md border border-gray-300 bg-white px-4 py-2 text-base font-medium text-gray-900 shadow-sm transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 data-[open]:bg-gray-50";

export const dropdownMenuPortalClasses = "contents";

export const dropdownMenuBackdropClasses = "fixed inset-0";

export const dropdownMenuPositionerClasses =
  "absolute left-0 top-full z-30 mt-2 min-w-56";

export const dropdownMenuPopupClasses =
  "w-56 overflow-hidden rounded-md border border-gray-200 bg-white p-1 shadow-lg outline-none";

export const dropdownMenuItemClasses =
  "flex w-full items-center justify-between gap-3 rounded-sm px-2 py-1.5 text-left text-sm text-gray-700 transition hover:bg-gray-100 focus:bg-gray-100 focus:outline-none data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const dropdownMenuInsetItemClasses = "pl-8";

export const dropdownMenuDestructiveItemClasses =
  "text-red-600 hover:bg-red-50 hover:text-red-700 focus:bg-red-50 focus:text-red-700";

export const dropdownMenuIconClasses =
  "flex size-4 shrink-0 items-center justify-center text-gray-500";

export const dropdownMenuIndicatorClasses =
  "flex size-4 shrink-0 items-center justify-center text-gray-950";

export const dropdownMenuSubContentClasses =
  "ml-1 min-w-44 rounded-md border border-gray-200 bg-white p-1 shadow-lg";

export const dropdownMenuLabelClasses =
  "px-2 py-1.5 text-sm font-semibold text-gray-950";

export const dropdownMenuSeparatorClasses = "-mx-1 my-1 h-px bg-gray-200";

export const dropdownMenuShortcutClasses =
  "ml-auto text-xs tracking-widest text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as DropdownMenu from "./index";

const view = (open: boolean): Html => {
  const h = html<string>();

  return DropdownMenu.rootView<string>({
    children: [
      DropdownMenu.triggerView<string>({
        open,
        onToggle: "toggle",
        children: [h.span([], ["Open"])],
      }),
      DropdownMenu.portalView<string>({
        open,
        children: [
          DropdownMenu.backdropView<string>({ onClose: "close" }),
          DropdownMenu.positionerView<string>({
            children: [
              DropdownMenu.popupView<string>({
                children: [
                  DropdownMenu.labelView<string>({
                    children: [h.span([], ["My Account"])],
                  }),
                  DropdownMenu.separatorView<string>({}),
                  DropdownMenu.itemView<string>({
                    onSelect: "profile",
                    children: [h.span([], ["Profile"])],
                  }),
                  DropdownMenu.itemView<string>({
                    onSelect: "billing",
                    children: [
                      h.span([], ["Billing"]),
                      DropdownMenu.shortcutView<string>("⌘B"),
                    ],
                  }),
                  DropdownMenu.separatorView<string>({}),
                  DropdownMenu.itemView<string>({
                    disabled: true,
                    onSelect: "disabled",
                    children: [h.span([], ["API"])],
                  }),
                  DropdownMenu.checkboxItemView<string>({
                    checked: true,
                    onSelect: "toggle-status",
                    children: [
                      DropdownMenu.itemIndicatorView<string>({
                        children: [h.span([], ["✓"])],
                      }),
                      h.span([], ["Status Bar"]),
                    ],
                  }),
                  DropdownMenu.radioGroupView<string>({
                    label: "Panel position",
                    children: [
                      DropdownMenu.radioItemView<string>({
                        checked: true,
                        onSelect: "panel-bottom",
                        children: [h.span([], ["Bottom"])],
                      }),
                    ],
                  }),
                  DropdownMenu.subTriggerView<string>({
                    open: true,
                    onOpen: "open-more-tools",
                    children: [h.span([], ["More Tools"]), h.span([], [">"])],
                  }),
                  DropdownMenu.subContentView<string>({
                    children: [
                      DropdownMenu.itemView<string>({
                        onSelect: "save-page",
                        children: [
                          DropdownMenu.iconView<string>({
                            children: [h.span([], ["□"])],
                          }),
                          h.span([], ["Save Page As..."]),
                        ],
                      }),
                    ],
                  }),
                  DropdownMenu.itemView<string>({
                    destructive: true,
                    onSelect: "delete",
                    children: [h.span([], ["Delete"])],
                  }),
                ],
              }),
            ],
          }),
        ],
      }),
    ],
  });
};

describe("Dropdown Menu registry view", () => {
  test("renders a closed trigger", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "Open" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.role("menu")).toBeAbsent()
    );
  });

  test("renders open menu items, shortcuts, separators, and disabled state", () => {
    Scene.scene(
      {
        update: (model: boolean): readonly [boolean, []] => [model, []],
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.role("button", { name: "Open" })).toHaveAttr(
        "aria-expanded",
        "true"
      ),
      Scene.expect(Scene.role("menu")).toExist(),
      Scene.expect(Scene.text("My Account")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "Profile" })).toExist(),
      Scene.expect(Scene.text("⌘B")).toHaveAttr(
        "data-slot",
        "dropdown-menu-shortcut"
      ),
      Scene.expect(Scene.role("separator")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "API" })).toHaveAttr(
        "data-disabled",
        "true"
      ),
      Scene.expect(Scene.text("Status Bar")).toExist(),
      Scene.expect(Scene.role("menuitemcheckbox")).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("group", { name: "Panel position" })).toExist(),
      Scene.expect(Scene.role("menuitemradio", { name: "Bottom" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.text("More Tools")).toExist(),
      Scene.expect(Scene.text("Save Page As...")).toExist(),
      Scene.expect(Scene.text("□")).toExist(),
      Scene.expect(Scene.role("menuitem", { name: "Delete" })).toHaveAttr(
        "data-variant",
        "destructive"
      )
    );
  });
});
